import{_ as o}from"./chunks/daily-2026-08-20-project-root-switch-figure-1.CFV2PKqm.js";import{_ as a,C as n,o as i,c as r,E as s,a2 as c}from"./chunks/framework.Cm6XCzck.js";const w=JSON.parse('{"title":"Why Is the Agent Still Editing the Old Project? Safely Rebinding an Execution Chain","description":"","frontmatter":{"title":"Why Is the Agent Still Editing the Old Project? Safely Rebinding an Execution Chain","date":"2026-08-20","column":"open-source-engineering","category":"daily","article_type":"project-research","edition":"research-center","research_question":"How can a local Agent execution chain rebind every project-scoped component without leaving hidden work attached to the old root?","summary":"Project switching is not a UI-label change. It must stop old effects, persist the new root, rebuild runtime and tool bindings, and verify one-root coherence while keeping Windows handles, symlink aliases, and graceful draining as explicit boundaries.","item_id":"MANUAL-20260820-PROJECT-ROOT","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-20-project-root-switch-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-fact-claim-matrices.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-experiment-run-log.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-independent-editorial-review-round4.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/03-independent-visual-package-review.md"]},"headers":[],"relativePath":"en/engineering/2026-08-20-project-root-switch.md","filePath":"en/engineering/2026-08-20-project-root-switch.md","lastUpdated":1787377515000}'),l={name:"en/engineering/2026-08-20-project-root-switch.md"};function d(h,e,p,u,m,g){const t=n("ArticleCover");return i(),r("div",null,[s(t,{image:"/assets/covers/daily-2026-08-20-project-root-switch-cover.png",kicker:"Open-source Engineering · Project Research",title:"Why Is the Agent Still Editing the Old Project? Safely Rebinding an Execution Chain",summary:"A safe switch stops old side effects, persists the new root, rebuilds every binding, and proves tasks and evidence now share one root.",version:"MANUAL-20260820-PROJECT-ROOT",status:"Community Readability PASS · 2026-08-22",languageHref:"/zh/engineering/2026-08-20-project-root-switch",languageLabel:"中文"}),e[0]||(e[0]=c(`<h1 id="why-is-the-agent-still-editing-the-old-project-safely-rebinding-an-execution-chain" tabindex="-1">Why Is the Agent Still Editing the Old Project? Safely Rebinding an Execution Chain <a class="header-anchor" href="#why-is-the-agent-still-editing-the-old-project-safely-rebinding-an-execution-chain" aria-label="Permalink to &quot;Why Is the Agent Still Editing the Old Project? Safely Rebinding an Execution Chain&quot;">​</a></h1><p>You switch the interface from project A to B, but the agent still patches A. Tests run in B while build output keeps contaminating A. Every local step looks successful; the delivery now combines two projects.</p><p>The model did not necessarily forget a name. The application had competing versions of “current project” in the UI, runtime, tool processes, watchers, and child-process working directories. A safe switch is therefore an ordered execution-chain rebind: stop new side effects in the old root, persist the new root, rebuild every project-scoped component from one binding plan, and verify that tasks and evidence land together. This article also covers Windows handles, symlink aliases, and draining failures that a selector cannot solve.</p><p>Think of a construction crew moving sites. The sign now says B, but workers are still demolishing A, the tool truck has reached B, cameras still watch A, and the inspector records everything in B’s notebook. Every participant followed an address; the combined project is still impossible to accept. A safe rebind moves the entire crew, not just the sign.</p><h2 id="current-project-is-not-one-string" tabindex="-1">“Current project” is not one string <a class="header-anchor" href="#current-project-is-not-one-string" aria-label="Permalink to &quot;“Current project” is not one string&quot;">​</a></h2><p>A local agent application commonly uses a project root in at least seven places:</p><table tabindex="0"><thead><tr><th>Component</th><th>Crew role</th><th>Failure when it keeps the old root</th></tr></thead><tbody><tr><td>runtime</td><td>site coordinator</td><td>starts sessions from old configuration</td></tr><tr><td>MCP server or tool process</td><td>tool truck</td><td>runs commands and file tools in the old directory</td></tr><tr><td>watcher</td><td>site camera</td><td>treats old-directory changes as current events</td></tr><tr><td>agent terminal and child-process <code>cwd</code></td><td>worker</td><td>writes, builds, and tests the wrong project</td></tr><tr><td>task admission and submission root</td><td>dispatch desk</td><td>files new work under the wrong project</td></tr><tr><td>FCoP lifecycle root</td><td>work ledger</td><td>mixes tasks, reports, and reviews</td></tr><tr><td>log and evidence root</td><td>acceptance archive</td><td>attributes old execution to the new project</td></tr></tbody></table><p>Switch six and leave one behind, and the system can produce a convincing cross-project fiction: code changes in A, a passing test in B, and a report attached to B’s task. Each local operation succeeded. The combined delivery is invalid.</p><p>The remedy can be remembered as four commands: <strong>stop old effects → lock the new address → issue one binding plan to the whole crew → verify task and evidence roots before reopening work.</strong></p><p>The <a href="https://nodejs.org/api/child_process.html" target="_blank" rel="noreferrer">Node.js child-process documentation</a> establishes one low-level fact: a child has an explicit <code>cwd</code>; without one, it inherits the parent’s current working directory, and a missing directory produces <code>ENOENT</code>. A UI label cannot retroactively change a process that is already running.</p><p>VS Code’s <a href="https://code.visualstudio.com/docs/editing/workspaces/multi-root-workspaces" target="_blank" rel="noreferrer">multi-root workspace documentation</a> gives another warning: an extension that has not adopted multi-root APIs may still operate only on the first folder. <a href="https://code.visualstudio.com/docs/editing/workspaces/workspace-trust" target="_blank" rel="noreferrer">Workspace Trust</a> evaluates newly added folders separately. Presence in a workspace, the root an extension uses, and the folder’s trust status are distinct facts.</p><h2 id="maintain-one-active-project-root" tabindex="-1">Maintain one active project root <a class="header-anchor" href="#maintain-one-active-project-root" aria-label="Permalink to &quot;Maintain one active project root&quot;">​</a></h2><p>CodeFlowMu’s <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/codeflowmu-shell/src/project-registry.ts" target="_blank" rel="noreferrer"><code>project-registry.ts</code></a> stores the active project and builds a runtime binding plan. The plan assigns one root to the runtime, MCP configuration, watchers, and Cursor agent working directory. A diagnostic compares the expected root, instance root, writer-lock root, and component bindings; disagreement produces <code>ACTIVE_PROJECT_BINDING_MISMATCH</code>.</p><p>That is safer than allowing every component to query “current project” independently. Component A can read A just before a switch while component B reads B just after it. Both values were current when read; the system is still split.</p><p>A single immutable plan avoids that race:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>active project root = D:/work/project-b</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Runtime root   ─┐</span></span>
<span class="line"><span>MCP root       ─┤</span></span>
<span class="line"><span>Watcher root   ─┼─ all must equal project-b</span></span>
<span class="line"><span>Agent cwd      ─┤</span></span>
<span class="line"><span>Writer lock    ─┘</span></span></code></pre></div><p>Equality should mean normalized path identity, not merely similar text. Windows adds case, separator, junction, and “business root versus its <code>fcop/</code> directory” complications.</p><p>Symlinks add another trap. <code>D:/work/app</code> and <code>D:/links/app</code> may refer to the same directory, and package managers such as pnpm use links extensively. The tested implementation mainly uses absolute resolution and business-root normalization; this article found no evidence that every binding is canonicalized through <code>fs.realpathSync.native()</code>. A hardened design should retain both the user-facing logical path and the operating-system real path, compare the latter for authority, and reject a missing target rather than guessing from strings.</p><h2 id="bind-each-request-to-an-immutable-context" tabindex="-1">Bind each request to an immutable context <a class="header-anchor" href="#bind-each-request-to-an-immutable-context" aria-label="Permalink to &quot;Bind each request to an immutable context&quot;">​</a></h2><p>Even after the process has an active project, a long request needs a stable context. Otherwise, a mid-request switch can make the first half read A and the second half write evidence to B.</p><p><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/project/ProjectExecutionContext.ts" target="_blank" rel="noreferrer"><code>ProjectExecutionContext</code></a> creates an immutable object at the request boundary. It binds the business project, runtime instance, data root, task-admission root, task-submission root, lifecycle root, and evidence root. Downstream components receive that object instead of rediscovering the project. A mismatched expected root raises <code>PROJECT_EXECUTION_CONTEXT_MISMATCH</code>.</p><p>This protects request-local consistency. It does not complete a hot switch. Old requests can still hold old contexts, which is why active sessions must be handled first.</p><h2 id="stop-the-old-world-before-constructing-the-new-one" tabindex="-1">Stop the old world before constructing the new one <a class="header-anchor" href="#stop-the-old-world-before-constructing-the-new-one" aria-label="Permalink to &quot;Stop the old world before constructing the new one&quot;">​</a></h2><p>The current public switch route lives in <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/codeflowmu-shell/src/web-panel.ts" target="_blank" rel="noreferrer"><code>web-panel.ts</code></a>. With switch-time reload enabled, its sequence is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Validate that the target exists and is not the protected installation source root</span></span>
<span class="line"><span>2. Cancel active agent sessions</span></span>
<span class="line"><span>3. If any session cannot stop, return a conflict and do not switch</span></span>
<span class="line"><span>4. Stop the old runtime</span></span>
<span class="line"><span>5. Persist the new active project and root</span></span>
<span class="line"><span>6. Apply project-scoped options</span></span>
<span class="line"><span>7. Invalidate and rebuild ledger state for the new root</span></span>
<span class="line"><span>8. Schedule shell/runtime reload</span></span>
<span class="line"><span>9. Let the UI wait until health reports the target projectRoot</span></span></code></pre></div><p><img src="`+o+'" alt="Project rebinding closes old effects, persists the new root, rebuilds all bindings, and verifies one root; draining, handle probes, and real-path checks are marked as recommended enhancements"></p><p><em>Figure 1. Execution-chain rebinding sequence. Source: author synthesis from the pinned CodeFlowMu implementation. The solid main path summarizes the current public implementation; the dashed draining, Windows-handle, and real-path checks are recommendations, not existing end-to-end functionality.</em></p><p>The decisive step is not refreshing the UI. It is closing the channels through which old-project work can continue producing effects.</p><p>This should not be called an atomic transaction. If persistence fails, the implementation restores the previous active-project identifier and attempts to restore the previous instance root. It cannot retract a request already sent to an external service, and it cannot prove that every third-party tool has discarded an in-memory path cache.</p><p>The accurate description is ordered stop, persist, rebuild, and verify, with bounded compensation.</p><h2 id="six-failure-modes-deserve-separate-treatment" tabindex="-1">Six failure modes deserve separate treatment <a class="header-anchor" href="#six-failure-modes-deserve-separate-treatment" aria-label="Permalink to &quot;Six failure modes deserve separate treatment&quot;">​</a></h2><h3 id="the-target-disappeared" tabindex="-1">The target disappeared <a class="header-anchor" href="#the-target-disappeared" aria-label="Permalink to &quot;The target disappeared&quot;">​</a></h3><p>The registry still contains B, but its directory has moved or been deleted. The current route refuses the switch. Startup resolution can fall back to an available instance root and emit a diagnostic.</p><p>Fallback itself is risky if the UI still says B. A control surface should show the effective root and the fallback reason, not only a friendly project name.</p><h3 id="an-old-session-will-not-stop" tabindex="-1">An old session will not stop <a class="header-anchor" href="#an-old-session-will-not-stop" aria-label="Permalink to &quot;An old session will not stop&quot;">​</a></h3><p>An agent may be waiting for a streamed model response, a build, or a long-running tool. The current switch route requests emergency cancellation and preserves the old project if any session cannot stop. That is correct fail-closed behavior, but it is not a complete graceful-drain protocol.</p><p>A stronger target sequence closes task admission, asks in-flight work to cancel cooperatively, allows a bounded grace window for writes and child processes, and then rechecks sessions, processes, and write leases. Timeout must not become success. Forced termination should be a last resort only for owned processes, after recording a dirty-state marker that requires repair or isolation before resuming.</p><p>If projects must run concurrently, separate runtime instances are cleaner than rapidly moving one global active root.</p><h3 id="persistence-fails" tabindex="-1">Persistence fails <a class="header-anchor" href="#persistence-fails" aria-label="Permalink to &quot;Persistence fails&quot;">​</a></h3><p>Memory has selected B, but the registry or instance record cannot be updated. The current implementation restores the old active identifier and attempts to write the old root back. That narrows the split window, but logs and a health check still need to confirm recovery.</p><h3 id="component-roots-disagree" tabindex="-1">Component roots disagree <a class="header-anchor" href="#component-roots-disagree" aria-label="Permalink to &quot;Component roots disagree&quot;">​</a></h3><p>The runtime says B while MCP still says A. Choosing the newest timestamp or taking a majority vote would hide the contradiction. The system should stop writes, report the mismatch, and let an authorized operator restart or restore.</p><p>This follows TMPA’s conflict-preservation rule: contradictory facts should remain visible rather than being smoothed into a probabilistic answer.</p><h3 id="windows-handles-remain-open" tabindex="-1">Windows handles remain open <a class="header-anchor" href="#windows-handles-remain-open" aria-label="Permalink to &quot;Windows handles remain open&quot;">​</a></h3><p>A cancellation acknowledgement does not prove that Git, a compiler, watcher, or child tool released its directory handles. Later cleanup or reconstruction can fail with <code>EBUSY</code>, <code>EPERM</code>, or access-denied errors. The 27 tests used here do not inject handle-retention faults.</p><p>Treat process stop and resource release as separate checks. Track owned children, use bounded backoff to probe active processes, watchers, leases, and critical paths, and preserve the old root when release cannot be established. Do not kill unrelated same-name processes or delete runtime directories while handle ownership is unknown.</p><h3 id="different-paths-resolve-to-the-same-directory" tabindex="-1">Different paths resolve to the same directory <a class="header-anchor" href="#different-paths-resolve-to-the-same-directory" aria-label="Permalink to &quot;Different paths resolve to the same directory&quot;">​</a></h3><p>Case, junctions, symlinks, mount aliases, and an accidental <code>fcop/</code> subdirectory can make string comparison lie in either direction. The current suite covers part of Windows normalization and <code>fcop/</code> handling, not universal symlink equivalence. Real-path identity should participate in registration, binding plans, and health checks; resolution failure should block the switch.</p><h2 id="a-switch-must-not-silently-initialize-the-target" tabindex="-1">A switch must not silently initialize the target <a class="header-anchor" href="#a-switch-must-not-silently-initialize-the-target" aria-label="Permalink to &quot;A switch must not silently initialize the target&quot;">​</a></h2><p>A newly selected project may lack FCoP assets or other runtime projections. Automatically copying them during a switch looks convenient, but selection and initialization carry different authority. Selection changes what the application observes; initialization writes into the target repository.</p><p>CodeFlowMu regression tests explicitly require project switching not to perform an unapproved Open-edition projection repair. Initialization belongs to a separate plan and administrator decision.</p><p>Otherwise, “open project B” silently becomes “modify project B,” which is especially unsafe for a freshly cloned external repository.</p><h2 id="what-27-passing-tests-establish" tabindex="-1">What 27 passing tests establish <a class="header-anchor" href="#what-27-passing-tests-establish" aria-label="Permalink to &quot;What 27 passing tests establish&quot;">​</a></h2><p>For this article we pinned CodeFlowMu Open commit <code>ed5634c718b9e238c44bb70851020c9793546fe6</code> in an isolated worktree and ran the runtime context and shell switch suites. The result was <strong>27 of 27 tests passing</strong>.</p><p>They cover immutable binding of task, submission, lifecycle, and evidence roots; normalization of an <code>fcop/</code> input without creating <code>fcop/fcop</code>; writer behavior during initialization; active-project registration; protection of the installation source root; missing or corrupt registry fallback; a shared binding plan for runtime, MCP, watchers, and Cursor working directory; consistent UI switch entry points; and the absence of unapproved projection repair during a switch.</p><p>The tests establish behavior of the pinned implementation. They do not prove that arbitrary third-party MCP servers, IDE extensions, or operating-system processes discard cached paths. They also do not cover high-frequency concurrent switches, graceful-drain timeout, Windows <code>EBUSY</code> handle retention, or symlink-alias races.</p><h2 id="a-switch-acceptance-checklist" tabindex="-1">A switch acceptance checklist <a class="header-anchor" href="#a-switch-acceptance-checklist" aria-label="Permalink to &quot;A switch acceptance checklist&quot;">​</a></h2><p>Before switching:</p><ol><li>Normalize and record the old and target absolute roots.</li><li>Reject the installation source root, unsafe parent roots, and missing targets.</li><li>List active sessions and components holding write leases.</li><li>Separate “select this project” from “initialize files in this project.”</li><li>Resolve the logical path to a real path and block missing, protected, or aliased targets.</li></ol><p>During switching:</p><ol start="6"><li>Close new task admission, then give old work a bounded drain window.</li><li>Recheck sessions, owned subprocesses, watchers, write leases, and Windows handles.</li><li>Persist the new root only after stop succeeds.</li><li>If persistence fails, record the compensation outcome.</li><li>Rebuild the runtime, MCP, watchers, and agent working directory from one plan.</li></ol><p>After switching:</p><ol start="11"><li>Have health report both logical and effective <code>projectRoot</code>, not only a project name.</li><li>Probe the task, lifecycle, and evidence roots.</li><li>Compare a root digest for every component and block writes on mismatch.</li><li>Run a temporary task and verify that its task file, code change, and report all land under the new root before resuming consequential work.</li></ol><p>Real-path identity, drain windows, handle probes, root digests, and the temporary acceptance task are recommendations from this analysis. They are not all implemented by the current switch route and are not FCoP protocol fields.</p><h2 id="applicability-limits" tabindex="-1">Applicability limits <a class="header-anchor" href="#applicability-limits" aria-label="Permalink to &quot;Applicability limits&quot;">​</a></h2><p>For a single-folder application with no background processes and no requirement for live switching, closing the application and restarting from the new root can be safer than hot rebind.</p><p>For genuine concurrent projects, a single active-root model is insufficient. Give each project its own runtime identity, processes, watchers, and evidence root, then let a higher control plane select which instance to observe.</p><p>Network filesystems, containers, and remote development introduce path mapping beyond the Windows-local tests used here. This article does not claim universal filesystem validation.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>When an agent edits the old project, the root cause is often not that the model forgot a name. The application mistook a UI selection for a completed execution-context rebind.</p><blockquote><p>The current project is not a label. It is a set of root-binding facts that must hold together.</p></blockquote><p>Stop old work, persist the new root, reconstruct every project-scoped component, verify the bindings, and only then resume. Skip one step and the agent may perform the correct operation in the wrong project.</p><h2 id="primary-sources" tabindex="-1">Primary sources <a class="header-anchor" href="#primary-sources" aria-label="Permalink to &quot;Primary sources&quot;">​</a></h2><ol><li><a href="https://nodejs.org/api/child_process.html" target="_blank" rel="noreferrer">Node.js Child Process: <code>cwd</code></a></li><li><a href="https://code.visualstudio.com/docs/editing/workspaces/multi-root-workspaces" target="_blank" rel="noreferrer">VS Code Multi-root Workspaces</a></li><li><a href="https://code.visualstudio.com/docs/editing/workspaces/workspace-trust" target="_blank" rel="noreferrer">VS Code Workspace Trust</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/project/ProjectExecutionContext.ts" target="_blank" rel="noreferrer">CodeFlowMu ProjectExecutionContext, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/codeflowmu-shell/src/project-registry.ts" target="_blank" rel="noreferrer">CodeFlowMu project-registry, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/codeflowmu-shell/src/web-panel.ts" target="_blank" rel="noreferrer">CodeFlowMu web-panel switch route, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/ae27de71b1a8809c2bd69acedc1482570d55a322/docs/public/releases/tmpa/v1.0/artifacts/tmpa-core-specification-s1.0-zh.md" target="_blank" rel="noreferrer">TMPA Core Specification S1.0, pinned commit</a></li></ol><p>Accessed 2026-08-20.</p>',75))])}const y=a(l,[["render",d]]);export{w as __pageData,y as default};
